    /** Explicit pure DTO control on a separate pool; never enters private World/Frame callbacks. */
    static void pureInitDelete(int stones,int attack,List<CdBigRing.ReadField> expected)throws Exception{
        var a=loaded();var real=body(a);var terrain=(CdR12bTerrainAssets)actualField(a.host(),"terrain");var placement=new CdObjectPlacementRuntime(terrain.placements());placement.pool().write(placement.pool().state(32).moveByte(ID,0x14));var reads=new ArrayList<CdBigRing.ReadField>();var draws=new ArrayList<CdBigRing.DrawCall>();var pure=new CdBigRing(placement,real.assets(),call->{reads.add(call.field());return switch(call.field()){case RINGS_WORD->50;case TIME_STONES_BYTE->stones;case TIME_ATTACK_BYTE->attack;default->throw new AssertionError("Unreached pure read "+call.field());};},null,null,null,null,call->{draws.add(call);placement.pool().write(call.expectedSource().moveByte(SPRITE_FLAGS,call.expectedSource().spriteFlags()&127));});var owner=a.h().mode().getRewindRegistry().capture();var result=pure.run(32);assertEquals(expected,reads);assertEquals(1,draws.size());assertEquals(0,draws.getFirst().expectedSource().id());assertArrayEquals(new byte[64],result.state().copyBytes());assertThrows(IllegalArgumentException.class,()->CdBigRing.fromAct2PastAssets(placement,terrain,null,null,null,null,null,call->{}));values(owner,a.h().mode().getRewindRegistry().capture(),"pure pool grants no World authority");healthy(a);
    }
