    record Control(int initialRings,int camera,int scrollLock,CdPlayerBody.State state,CdPlayerBody.Environment environment){CdPlayerMotionState motion(){return state.motion();}}
    static Control collectAndParent(A a,int whole)throws Exception{var c=prepareCollectors(a,whole);forward(a);return c;}
    static Control prepareCollectors(A a,int whole)throws Exception{
        sameChunk(a);var p=a.host().placement().pool();p.clearDynamicSlots();int initial=a.host().globals().ring().rings();assertTrue(initial<50);var registry=a.h().mode().getRewindRegistry();int camera=a.host().scroll().foreground().cameraX(),lock=a.host().scroll().foreground().scrollLock();var before=registry.capture();forward(a);var state=a.frame().state();var environment=a.frame().environment();registry.restore(before);sameChunk(a);
        // Explicit collection-state ingress. No counter is assigned: physical32..81 each run the
        // existing LostRing/CollectRing owner before the sole parent127. Original owner may fault.
        for(int n=32;n<82;n++)p.write(p.state(n).moveByte(ID,0x11).moveByte(ROUTINE,4).moveLong(MAPPINGS,0x209EB0).moveWord(TILE,0xA7AE).moveWord(X,(state.motion().centreX16_16()>>>16)-100&65535).moveWord(Y,state.motion().centreY16_16()>>>16));
        p.write(p.state(whole).moveByte(ID,0x14).moveWord(X,state.motion().centreX16_16()>>>16).moveWord(Y,state.motion().centreY16_16()>>>16));return new Control(initial,camera,lock,state,environment);
    }
    static void flash(A a,int routine,int subtype)throws Exception{seed(a,0x14,routine);var p=a.host().placement().pool();p.write(p.state(32).moveByte(SUBTYPE,subtype).moveByte(SPRITE_FLAGS,4).moveLong(MAPPINGS,body(a).assets().flashMappingsAddress()).moveWord(TILE,0x03EF));}
    static SonicCdAct2PastObjectPass pass(A a)throws Exception{return (SonicCdAct2PastObjectPass)actualField(actualField(a.core(),"ordinary"),"objects");}
    static CdBigRing body(A a)throws Exception{return (CdBigRing)actualField(pass(a),"bigRing");}
    static long bigSounds(A a)throws Exception{return sounds(a).stream().filter(SonicCdGameModule.PastBigRingFm.class::isInstance).count();}
    static void healthy(A a)throws Exception{assertFalse(a.frame().closed());assertNull(actualField(pass(a),"bigRingInvocation"));assertFalse((boolean)actualField(pass(a),"bigRingBorrow"));assertNull(actualField(pass(a),"pending"));}
