    static CdObjectState animate(CdObjectState s,CdAssetBytes bytes){var o=CdObjectAnimation.step(new CdObjectAnimation.State(s.unsignedByte(ANIMATION),s.unsignedByte(PREVIOUS_ANIMATION),s.unsignedByte(ANIMATION_FRAME),s.unsignedByte(ANIMATION_TIME),s.unsignedByte(MAP_FRAME),s.spriteFlags(),s.flags(),s.routine(),s.unsignedByte(ROUTINE_2)),new CdObjectAnimation.AnimationTable(bytes,0,1));return s.moveByte(ANIMATION,o.animationId()).moveByte(PREVIOUS_ANIMATION,o.previousId()).moveByte(ANIMATION_FRAME,o.scriptIndex()).moveByte(ANIMATION_TIME,o.timer()).moveByte(MAP_FRAME,o.mapFrame()).moveByte(SPRITE_FLAGS,o.spriteFlags()).moveByte(FLAGS,o.statusFlags()).moveByte(ROUTINE,o.routine()).moveByte(ROUTINE_2,o.routine2());}
